core_reasoning_1:
\textbf{Claim.} For a pure state $|\Psi^{ABC}\rangle$ whose subsystem $B$ is measured in a product basis, the average measurement-induced entanglement is exactly the conditional entropy of $A$ given the classical measurement register $M_B$:
\[
E(A:C)=\sum_{s_B}p_{s_B}S(\rho^A_{s_B})=S(A\mid M_B)_\rho .
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & p_{s_B}:=\langle s_B|\rho^B|s_B\rangle,\quad \sum_{s_B}p_{s_B}=1,\quad p_{s_B}\ge 0.\\
(P2) & |\phi^{AC}_{s_B}\rangle:=p_{s_B}^{-1/2}(\langle s_B|\otimes I_{AC})|\Psi^{ABC}\rangle.\\
(P3) & \rho^A_{s_B}:=\operatorname{Tr}_C(|\phi^{AC}_{s_B}\rangle\langle\phi^{AC}_{s_B}|).\\
(P4) & \rho^{AM_B}:=\sum_{s_B}p_{s_B}\rho^A_{s_B}\otimes |s_B\rangle\langle s_B|.\\
(P5) & S(A\mid M_B)_\rho:=S(AM_B)_\rho-S(M_B)_\rho.\\
(P6) & \text{If }\omega=\sum_s p_s\omega_s\otimes |s\rangle\langle s|\text{ with orthogonal }|s\rangle,\\
     & S(\omega)=-\sum_s p_s\log p_s+\sum_s p_sS(\omega_s).\\
(P7) & E(A:C):=\sum_{s_B}p_{s_B}S(\rho^A_{s_B}).
\end{array}
\]

\textbf{Derivation.}
\begin{align}
S(AM_B)_\rho
&=S\left(\sum_{s_B}p_{s_B}\rho^A_{s_B}\otimes |s_B\rangle\langle s_B|\right) && \text{by (P4)}\\
&=-\sum_{s_B}p_{s_B}\log p_{s_B}+\sum_{s_B}p_{s_B}S(\rho^A_{s_B}) && \text{by (P6)}.
\end{align}
The marginal on $M_B$ is
\begin{align}
\rho^{M_B}
&=\operatorname{Tr}_A(\rho^{AM_B}) && \text{definition of marginal}\\
&=\sum_{s_B}p_{s_B}\operatorname{Tr}(\rho^A_{s_B})|s_B\rangle\langle s_B| && \text{by (P4)}\\
&=\sum_{s_B}p_{s_B}|s_B\rangle\langle s_B|, && \text{since }\operatorname{Tr}(\rho^A_{s_B})=1
\end{align}
so
\begin{align}
S(M_B)_\rho
&=-\sum_{s_B}p_{s_B}\log p_{s_B} && \text{classical entropy of the diagonal state}.
\end{align}
Substitution into the conditional entropy gives
\begin{align}
S(A\mid M_B)_\rho
&=S(AM_B)_\rho-S(M_B)_\rho && \text{by (P5)}\\
&=\left[-\sum_{s_B}p_{s_B}\log p_{s_B}+\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\right]
  -\left[-\sum_{s_B}p_{s_B}\log p_{s_B}\right] && \text{substitution}\\
&=\sum_{s_B}p_{s_B}S(\rho^A_{s_B}) && \text{cancellation}\\
&=E(A:C). && \text{by (P7)}
\end{align}

\textbf{Final Result.}
\[
\boxed{E(A:C)=\sum_{s_B}p_{s_B}S(\rho^A_{s_B})=S(A\mid M_B)_\rho.}
\]
\hfill$\blacksquare$

core_reasoning_2:
\textbf{Claim.} If the one-shot distillation protocol applied after the measurements on $B$ has average trace-distance error $\epsilon$, then
\[
\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge \left(1-\frac{\epsilon}{2}\right)\log d'-h_2\left(\frac{\epsilon}{2}\right),
\]
where $h_2(x):=-x\log x-(1-x)\log(1-x)$.

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & \rho^A_{s_B}:=\operatorname{Tr}_C(\phi^{AC}_{s_B}).\\
(P2) & \{(p_{r_A\mid s_B},\chi^{A'C}_{r_As_B})\}_{r_A}\text{ is produced from }\phi^{AC}_{s_B}\text{ by LOCC}.\\
(P3) & \rho^{A'}_{r_As_B}:=\operatorname{Tr}_C(\chi^{A'C}_{r_As_B}),\quad \pi^{A'}:=I_{A'}/d'.\\
(P4) & \epsilon_{s_B}:=\sum_{r_A}p_{r_A\mid s_B}\|\rho^{A'}_{r_As_B}-\pi^{A'}\|_1.\\
(P5) & \epsilon:=\sum_{s_B}p_{s_B}\epsilon_{s_B}.\\
(P6) & S(\rho^A_{s_B})\ge \sum_{r_A}p_{r_A\mid s_B}S(\rho^{A'}_{r_As_B})\quad\text{for LOCC on pure states}.\\
(P7) & \text{If }T(\omega,\sigma):=\frac12\|\omega-\sigma\|_1,\text{ then }\\
     & |S(\omega)-S(\sigma)|\le T(\omega,\sigma)\log d+h_2(T(\omega,\sigma)).\\
(P8) & S(\pi^{A'})=\log d'.\\
(P9) & h_2\text{ is concave on }[0,1].
\end{array}
\]

\textbf{Derivation.}
For fixed $s_B$, define
\begin{align}
T_{r_As_B}&:=\frac12\|\rho^{A'}_{r_As_B}-\pi^{A'}\|_1. && \text{definition}
\end{align}
Then
\begin{align}
\sum_{r_A}p_{r_A\mid s_B}T_{r_As_B}
&=\frac12\sum_{r_A}p_{r_A\mid s_B}\|\rho^{A'}_{r_As_B}-\pi^{A'}\|_1 && \text{definition of }T_{r_As_B}\\
&=\frac{\epsilon_{s_B}}{2}. && \text{by (P4)}
\end{align}
By the continuity bound,
\begin{align}
S(\rho^{A'}_{r_As_B})
&\ge S(\pi^{A'})-T_{r_As_B}\log d'-h_2(T_{r_As_B}) && \text{by (P7)}\\
&=(1-T_{r_As_B})\log d'-h_2(T_{r_As_B}) && \text{by (P8)}.
\end{align}
Averaging over $r_A$ and using LOCC monotonicity gives
\begin{align}
S(\rho^A_{s_B})
&\ge \sum_{r_A}p_{r_A\mid s_B}S(\rho^{A'}_{r_As_B}) && \text{by (P6)}\\
&\ge \sum_{r_A}p_{r_A\mid s_B}\left[(1-T_{r_As_B})\log d'-h_2(T_{r_As_B})\right] && \text{previous bound}\\
&=\left(1-\sum_{r_A}p_{r_A\mid s_B}T_{r_As_B}\right)\log d'-\sum_{r_A}p_{r_A\mid s_B}h_2(T_{r_As_B}) && \text{linearity}\\
&\ge \left(1-\frac{\epsilon_{s_B}}{2}\right)\log d'-h_2\left(\frac{\epsilon_{s_B}}{2}\right) && \text{by (P9) and the value of the mean}.
\end{align}
Now average over $s_B$:
\begin{align}
\sum_{s_B}p_{s_B}S(\rho^A_{s_B})
&\ge \sum_{s_B}p_{s_B}\left[\left(1-\frac{\epsilon_{s_B}}{2}\right)\log d'-h_2\left(\frac{\epsilon_{s_B}}{2}\right)\right] && \text{previous bound}\\
&=\left(1-\frac{1}{2}\sum_{s_B}p_{s_B}\epsilon_{s_B}\right)\log d'-\sum_{s_B}p_{s_B}h_2\left(\frac{\epsilon_{s_B}}{2}\right) && \text{linearity}\\
&\ge \left(1-\frac{\epsilon}{2}\right)\log d'-h_2\left(\frac{\epsilon}{2}\right) && \text{by (P5) and concavity (P9)}.
\end{align}

\textbf{Final Result.}
\[
\boxed{\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge \left(1-\frac{\epsilon}{2}\right)\log d'-h_2\left(\frac{\epsilon}{2}\right).}
\]
\hfill$\blacksquare$

core_reasoning_3:
\textbf{Claim.} For any $\delta>\log 2$, the pre-averaged distillation bound implies
\[
\Pr_{s_B,U}\!\left(S(\rho^A_{s_B})<\log d'-\delta\right)
\le \frac{\mathbb E_U[\epsilon]\log d'}{2(\delta-\log 2)}.
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & S(\rho^A_{s_B})\ge \left(1-\frac{\epsilon_{s_B}}{2}\right)\log d'-h_2\left(\frac{\epsilon_{s_B}}{2}\right).\\
(P2) & 0\le \epsilon_{s_B}\le 2.\\
(P3) & h_2(x)\le \log 2\text{ for }0\le x\le 1.\\
(P4) & \epsilon:=\sum_{s_B}p_{s_B}\epsilon_{s_B}.\\
(P5) & \text{If }X\ge 0\text{ and }a>0,\text{ then }\Pr(X>a)\le \mathbb E[X]/a.\\
(P6) & \delta>\log 2.
\end{array}
\]

\textbf{Derivation.}
For every outcome and circuit instance,
\begin{align}
S(\rho^A_{s_B})
&\ge \left(1-\frac{\epsilon_{s_B}}{2}\right)\log d'-\log 2 && \text{by (P1)--(P3)}\\
&=\log d'-\frac{\epsilon_{s_B}}{2}\log d'-\log 2. && \text{algebra}
\end{align}
Therefore the event $S(\rho^A_{s_B})<\log d'-\delta$ implies
\begin{align}
\log d'-\frac{\epsilon_{s_B}}{2}\log d'-\log 2
&<\log d'-\delta && \text{event inclusion}\\
\frac{\epsilon_{s_B}}{2}\log d'
&>\delta-\log 2. && \text{rearrange, using (P6)}
\end{align}
Hence
\begin{align}
\Pr_{s_B,U}\!\left(S(\rho^A_{s_B})<\log d'-\delta\right)
&\le \Pr_{s_B,U}\!\left(\frac{\epsilon_{s_B}}{2}\log d'>\delta-\log 2\right) && \text{event inclusion}\\
&\le \frac{\mathbb E_{s_B,U}[\epsilon_{s_B}\log d'/2]}{\delta-\log 2} && \text{by (P5)}\\
&=\frac{\mathbb E_U\left[\sum_{s_B}p_{s_B}\epsilon_{s_B}\right]\log d'}{2(\delta-\log 2)} && \text{average over }s_B\\
&=\frac{\mathbb E_U[\epsilon]\log d'}{2(\delta-\log 2)}. && \text{by (P4)}
\end{align}

\textbf{Final Result.}
\[
\boxed{\Pr_{s_B,U}\!\left(S(\rho^A_{s_B})<\log d'-\delta\right)
\le \frac{\mathbb E_U[\epsilon]\log d'}{2(\delta-\log 2)}.}
\]
\hfill$\blacksquare$

core_reasoning_4:
\textbf{Claim.} The multiparty splitting expansion rewrites the average distillation error as a trace norm of a sum over subsets $I\subseteq B$, equivalently Ising configurations with boundary values $\sigma_A=-1$ and $\sigma_C=+1$:
\[
\epsilon=\left\|\sum_{I\subseteq B}\left(\Theta_A\otimes\Theta_I\otimes\widehat D_{B\setminus I}\otimes\operatorname{Tr}_C\right)[\Psi^{ABC}]\right\|_1.
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & D_X[\omega^X]:=\pi^X\operatorname{Tr}(\omega^X),\quad \pi^X:=I_X/d_X.\\
(P2) & \Theta_A:=(\operatorname{id}_{A'}-D_{A'})\circ T^{A\to A'M_A}.\\
(P3) & T^{Q_i\to M_i}=\Theta_i+\widehat D_i,\quad
        \Theta_i:=T^{Q_i\to M_i}\circ(\operatorname{id}_{Q_i}-D_{Q_i}),\\
     & \widehat D_i:=T^{Q_i\to M_i}\circ D_{Q_i}.\\
(P4) & T^{B\to M_B}:=\bigotimes_{i\in B}T^{Q_i\to M_i}.\\
(P5) & \Theta_I:=\bigotimes_{i\in I}\Theta_i,\quad
        \widehat D_{B\setminus I}:=\bigotimes_{j\in B\setminus I}\widehat D_j.\\
(P6) & \epsilon=\|\left(\Theta_A\otimes T^{B\to M_B}\otimes\operatorname{Tr}_C\right)[\Psi^{ABC}]\|_1.\\
(P7) & \bigotimes_{i\in B}(X_i+Y_i)=\sum_{I\subseteq B}\left(\bigotimes_{i\in I}X_i\right)\otimes\left(\bigotimes_{j\in B\setminus I}Y_j\right).
\end{array}
\]

\textbf{Derivation.}
The product measurement channel expands as
\begin{align}
T^{B\to M_B}
&=\bigotimes_{i\in B}T^{Q_i\to M_i} && \text{by (P4)}\\
&=\bigotimes_{i\in B}(\Theta_i+\widehat D_i) && \text{by (P3)}\\
&=\sum_{I\subseteq B}\Theta_I\otimes\widehat D_{B\setminus I}. && \text{by (P5) and (P7)}
\end{align}
Substituting this expansion into the expression for $\epsilon$ gives
\begin{align}
\epsilon
&=\left\|\left(\Theta_A\otimes T^{B\to M_B}\otimes\operatorname{Tr}_C\right)[\Psi^{ABC}]\right\|_1 && \text{by (P6)}\\
&=\left\|\left(\Theta_A\otimes \sum_{I\subseteq B}\Theta_I\otimes\widehat D_{B\setminus I}\otimes\operatorname{Tr}_C\right)[\Psi^{ABC}]\right\|_1 && \text{substitution}\\
&=\left\|\sum_{I\subseteq B}\left(\Theta_A\otimes\Theta_I\otimes\widehat D_{B\setminus I}\otimes\operatorname{Tr}_C\right)[\Psi^{ABC}]\right\|_1. && \text{linearity}
\end{align}
For the Ising interpretation define
\begin{align}
\sigma_i&:=\begin{cases}-1,&i\in I,\\ +1,&i\notin I,\end{cases}
&\sigma_A&:=-1,&\sigma_C&:=+1. && \text{definition}
\end{align}
Thus each subset $I$ labels one spin configuration with the fixed boundary spins stated in the claim.

\textbf{Final Result.}
\[
\boxed{\epsilon=\left\|\sum_{I\subseteq B}\left(\Theta_A\otimes\Theta_I\otimes\widehat D_{B\setminus I}\otimes\operatorname{Tr}_C\right)[\Psi^{ABC}]\right\|_1.}
\]
\hfill$\blacksquare$

core_reasoning_7:
\textbf{Claim.} Let $F_{\mathrm{SAW}}:=-\log Z_{\mathrm{SAW}}$. If $F_{\mathrm{SAW}}\ge 2$, optimizing the rank $d'$ in the entanglement-of-assistance bound gives
\[
\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge 2F_{\mathrm{SAW}}-2\log(eF_{\mathrm{SAW}}).
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & F:=F_{\mathrm{SAW}}=-\log Z_{\mathrm{SAW}},\quad F\ge 2.\\
(P2) & g(F):=e^{e^{-F}}-1.\\
(P3) & \epsilon\le \sqrt{d'}\,g(F).\\
(P4) & \sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge \left(1-\frac{\epsilon}{2}\right)\log d'-h_2\left(\frac{\epsilon}{2}\right).\\
(P5) & d':=\left\lceil F^{-2}e^{2F}\right\rceil.\\
(P6) & \lceil a\rceil\le 2a\text{ for }a\ge 1.\\
(P7) & e^y-1\le ye^y\text{ for }y\ge 0.\\
(P8) & e^{-F}\le 1/4\text{ for }F\ge 2,\quad \sqrt{2}e^{1/4}\le 2.\\
(P9) & h_2\text{ is increasing on }[0,1/2],\quad h_2(y)\le 2y\log(1/y)\text{ for }0<y\le 1/2.\\
(P10) & \log d'\ge 2F-2\log F.
\end{array}
\]

\textbf{Derivation.}
Let
\begin{align}
a&:=F^{-2}e^{2F}. && \text{definition}
\end{align}
Since $F\ge 2$, $a\ge 1$. Therefore
\begin{align}
\sqrt{d'}
&=\sqrt{\lceil a\rceil} && \text{by (P5)}\\
&\le \sqrt{2a} && \text{by (P6)}\\
&=\sqrt{2}\,F^{-1}e^F. && \text{substitute }a
\end{align}
Also,
\begin{align}
g(F)
&=e^{e^{-F}}-1 && \text{by (P2)}\\
&\le e^{-F}e^{e^{-F}} && \text{by (P7) with }y=e^{-F}\\
&\le e^{-F}e^{1/4}. && \text{by (P8)}
\end{align}
Hence
\begin{align}
\epsilon
&\le \sqrt{d'}g(F) && \text{by (P3)}\\
&\le \sqrt{2}F^{-1}e^F\,e^{-F}e^{1/4} && \text{previous two bounds}\\
&\le \frac{2}{F}. && \text{by (P8)}
\end{align}
Thus $0\le \epsilon/2\le 1/F\le 1/2$. From (P9),
\begin{align}
h_2\left(\frac{\epsilon}{2}\right)
&\le h_2\left(\frac1F\right) && \text{monotonicity in (P9)}\\
&\le \frac{2}{F}\log F. && \text{entropy bound in (P9)}
\end{align}
Substituting these estimates into the entanglement lower bound gives
\begin{align}
\sum_{s_B}p_{s_B}S(\rho^A_{s_B})
&\ge \left(1-\frac{\epsilon}{2}\right)\log d'-h_2\left(\frac{\epsilon}{2}\right) && \text{by (P4)}\\
&\ge \left(1-\frac1F\right)\log d'-\frac{2}{F}\log F && \text{using }\epsilon/2\le 1/F\\
&\ge \left(1-\frac1F\right)(2F-2\log F)-\frac{2}{F}\log F && \text{by (P10)}\\
&=2F-2\log F-2+\frac{2\log F}{F}-\frac{2\log F}{F} && \text{expand}\\
&=2F-2\log F-2 && \text{cancel}\\
&=2F-2\log(eF). && \text{since }\log(eF)=1+\log F
\end{align}

\textbf{Final Result.}
\[
\boxed{\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge 2F_{\mathrm{SAW}}-2\log(eF_{\mathrm{SAW}}).}
\]
\hfill$\blacksquare$

core_reasoning_8:
\textbf{Claim.} In a random holographic circuit, if every bond state has $S_e^{(2)}>2\log\mu_{\Lambda^*}$ and $L_y$ is polynomial in $L_x$, then the average measurement-induced entanglement is extensive:
\[
\mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge \kappa L_x
\]
for all sufficiently large $L_x$, with $\kappa>0$ arbitrarily close to $S_e^{(2)}-2\log\mu_{\Lambda^*}$.

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & H[W]=\frac12S_e^{(2)}|W|\text{ for every separating wall }W.\\
(P2) & \beta:=S_e^{(2)}/2,\quad \beta_{\mathrm{crit}}:=\log\mu_{\Lambda^*},\quad \beta>\beta_{\mathrm{crit}}.\\
(P3) & \text{For every }\eta\text{ with }0<\eta<\beta-\beta_{\mathrm{crit}},\\
     & Z_{\mathrm{SAW}}\le L_y\exp[-(\beta-\beta_{\mathrm{crit}}-\eta)L_x]\text{ for all sufficiently large }L_x.\\
(P4) & L_y\le L_x^a\text{ for some fixed }a>0.\\
(P5) & F_{\mathrm{SAW}}:=-\log Z_{\mathrm{SAW}}.\\
(P6) & \mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge 2F_{\mathrm{SAW}}-2\log(eF_{\mathrm{SAW}})\text{ when }F_{\mathrm{SAW}}\ge 2.
\end{array}
\]

\textbf{Derivation.}
Choose $\eta$ with $0<\eta<\beta-\beta_{\mathrm{crit}}$ and define
\begin{align}
\alpha&:=\beta-\beta_{\mathrm{crit}}-\eta. && \text{definition}
\end{align}
By (P2), $\alpha>0$. The partition-function estimate gives
\begin{align}
F_{\mathrm{SAW}}
&=-\log Z_{\mathrm{SAW}} && \text{by (P5)}\\
&\ge -\log\left(L_y e^{-\alpha L_x}\right) && \text{by (P3)}\\
&=\alpha L_x-\log L_y && \text{algebra}\\
&\ge \alpha L_x-a\log L_x. && \text{by (P4)}
\end{align}
Thus $F_{\mathrm{SAW}}\ge 2$ for all sufficiently large $L_x$. Applying the optimized lower bound,
\begin{align}
\mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})
&\ge 2F_{\mathrm{SAW}}-2\log(eF_{\mathrm{SAW}}) && \text{by (P6)}\\
&\ge 2(\alpha L_x-a\log L_x)-2\log(eF_{\mathrm{SAW}}) && \text{lower bound on }F_{\mathrm{SAW}}.
\end{align}
Since $F_{\mathrm{SAW}}$ grows at most linearly up to polynomial factors in the geometry under consideration, the logarithmic term is $o(L_x)$. Hence for every $\eta'>0$ there is an $L_0$ such that $L_x\ge L_0$ implies
\begin{align}
\mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})
&\ge (2\alpha-\eta')L_x && \text{absorb sublinear terms}\\
&=(S_e^{(2)}-2\log\mu_{\Lambda^*}-2\eta-\eta')L_x. && \text{substitute }\alpha
\end{align}
Because $\eta$ and $\eta'$ can be chosen arbitrarily small positive constants, any positive $\kappa<S_e^{(2)}-2\log\mu_{\Lambda^*}$ is achievable for large enough $L_x$.

\textbf{Final Result.}
\[
\boxed{\mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge \kappa L_x\quad\text{for any }0<\kappa<S_e^{(2)}-2\log\mu_{\Lambda^*}.}
\]
\hfill$\blacksquare$

core_reasoning_10:
\textbf{Claim.} For depth-$4$ Haar-random two-qudit brickwork circuits with local Hilbert-space dimension $q\ge 134$, measuring $B$ in the geometry of the paper yields extensive average post-measurement entanglement:
\[
\mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge \kappa L_x
\]
for some constant $\kappa>0$ and all sufficiently large $L_x$.

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & \text{A depth-}4\text{ brickwork circuit compiles into the same blocked geometry as a depth-}2\text{ }4\text{-local circuit}.\\
(P2) & \text{Appendix-E brickwork analysis gives }\|T_r\|_1\le \sqrt{d'}G_{\mathrm{bw}}(q)^{|W|}.\\
(P3) & \text{For }q\ge 134\text{, }G_{\mathrm{bw}}(q)\mu_{\Lambda^*}\le e^{-\eta_{\mathrm{bw}}}\text{ for some }\eta_{\mathrm{bw}}>0.\\
(P4) & \text{The number of length-}\ell\text{ separating walks is at most }L_y\mu_{\Lambda^*}^{\ell},\quad \ell\ge L_x.\\
(P5) & L_y\le L_x^a\text{ for some fixed }a>0.\\
(P6) & F_{\mathrm{bw}}:=-\log Z_{\mathrm{bw}},\quad Z_{\mathrm{bw}}:=\sum_W G_{\mathrm{bw}}(q)^{|W|}.\\
(P7) & \mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge 2F_{\mathrm{bw}}-2\log(eF_{\mathrm{bw}})\text{ when }F_{\mathrm{bw}}\ge 2.
\end{array}
\]

\textbf{Derivation.}
The partition function for the brickwork bound satisfies
\begin{align}
Z_{\mathrm{bw}}
&=\sum_W G_{\mathrm{bw}}(q)^{|W|} && \text{by (P6)}\\
&\le \sum_{\ell=L_x}^{\infty}L_y\mu_{\Lambda^*}^{\ell}G_{\mathrm{bw}}(q)^{\ell} && \text{by (P4)}\\
&=L_y\sum_{\ell=L_x}^{\infty}\left(\mu_{\Lambda^*}G_{\mathrm{bw}}(q)\right)^{\ell} && \text{factor terms}\\
&\le L_y\sum_{\ell=L_x}^{\infty}e^{-\eta_{\mathrm{bw}}\ell} && \text{by (P3)}\\
&=\frac{L_y e^{-\eta_{\mathrm{bw}}L_x}}{1-e^{-\eta_{\mathrm{bw}}}}. && \text{geometric series}
\end{align}
Consequently,
\begin{align}
F_{\mathrm{bw}}
&=-\log Z_{\mathrm{bw}} && \text{by (P6)}\\
&\ge \eta_{\mathrm{bw}}L_x-\log L_y+\log(1-e^{-\eta_{\mathrm{bw}}}) && \text{take }-\log\\
&\ge \eta_{\mathrm{bw}}L_x-a\log L_x+\log(1-e^{-\eta_{\mathrm{bw}}}) && \text{by (P5)}.
\end{align}
For sufficiently large $L_x$, $F_{\mathrm{bw}}\ge 2$. Hence
\begin{align}
\mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})
&\ge 2F_{\mathrm{bw}}-2\log(eF_{\mathrm{bw}}) && \text{by (P7)}\\
&\ge 2\eta_{\mathrm{bw}}L_x-2a\log L_x+2\log(1-e^{-\eta_{\mathrm{bw}}})-2\log(eF_{\mathrm{bw}}). && \text{substitution}
\end{align}
The non-linear terms are $o(L_x)$, so the lower bound is at least $\eta_{\mathrm{bw}}L_x$ for large enough $L_x$. Let $\kappa:=\eta_{\mathrm{bw}}>0$.

\textbf{Final Result.}
\[
\boxed{q\ge 134\quad\Longrightarrow\quad \mathbb E_U\sum_{s_B}p_{s_B}S(\rho^A_{s_B})\ge \kappa L_x\text{ for some }\kappa>0.}
\]
\hfill$\blacksquare$

core_reasoning_11:
\textbf{Claim.} In the ordered self-avoiding-walk regime relevant to SEBD or boundary-MPS contraction, a virtual state has half-chain entropy $\Omega(\sqrt N)$ with probability $1-e^{-\Omega(\sqrt N)}$ on an $\sqrt N\times\sqrt N$ system; therefore any algorithm capped at polynomial MPS bond dimension aborts with probability $1-e^{-\Omega(\sqrt N)}$.

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & \xi:=\min(t,L_x/2)\text{ is the minimum distance travelled by a relevant separating walk}.\\
(P2) & \mathbb E_U[\epsilon]\le \sqrt{d'}e^{-m\xi}\text{ for some constant }m>0.\\
(P3) & d':=e^{\alpha\xi}\text{ with }0<\alpha<2m.\\
(P4) & \Pr_{s_B,U}\left(S(\rho^A_{s_B})<\log d'-2\log 2\right)\le \frac12\mathbb E_U[\epsilon]\log d'.\\
(P5) & \text{An exact MPS of bond dimension }\chi\text{ has half-chain entropy at most }\log\chi.\\
(P6) & \text{A polynomial bond-dimension cap has }\log\chi=O(\log N).\\
(P7) & \text{For a square system, }L_x=\sqrt N\text{ and one can take }\xi=L_x/2=\sqrt N/2.\\
(P8) & \text{The algorithm aborts when the required bond dimension exceeds the cap.}
\end{array}
\]

\textbf{Derivation.}
The mean error is exponentially small in $\xi$:
\begin{align}
\mathbb E_U[\epsilon]
&\le \sqrt{d'}e^{-m\xi} && \text{by (P2)}\\
&=e^{\alpha\xi/2}e^{-m\xi} && \text{by (P3)}\\
&=e^{-(m-\alpha/2)\xi}. && \text{combine exponents}
\end{align}
Define
\begin{align}
c&:=m-\alpha/2>0. && \text{by (P3)}
\end{align}
Using the concentration bound,
\begin{align}
\Pr_{s_B,U}\left(S(\rho^A_{s_B})<\log d'-2\log 2\right)
&\le \frac12\mathbb E_U[\epsilon]\log d' && \text{by (P4)}\\
&\le \frac12e^{-c\xi}\alpha\xi && \text{by }\log d'=\alpha\xi\\
&=e^{-\Omega(\xi)}. && \text{exponential dominates polynomial}
\end{align}
Thus with probability at least $1-e^{-\Omega(\xi)}$,
\begin{align}
S(\rho^A_{s_B})
&\ge \log d'-2\log 2 && \text{complement event}\\
&=\alpha\xi-2\log 2 && \text{by (P3)}\\
&=\Omega(\xi). && \text{as }\xi\to\infty
\end{align}
For a square system,
\begin{align}
S(\rho^A_{s_B})&=\Omega(\sqrt N) && \text{by (P7)},\\
\Pr\left(S(\rho^A_{s_B})=\Omega(\sqrt N)\right)&\ge 1-e^{-\Omega(\sqrt N)} && \text{by (P7)}.
\end{align}
If this state had a polynomial-bond-dimension exact MPS representation, then
\begin{align}
S(\rho^A_{s_B})
&\le \log\chi && \text{by (P5)}\\
&=O(\log N), && \text{by (P6)}
\end{align}
which contradicts $S(\rho^A_{s_B})=\Omega(\sqrt N)$ for sufficiently large $N$. Therefore the polynomial-cap algorithm must abort on the high-entropy event.

\textbf{Final Result.}
\[
\boxed{\Pr(\text{SEBD or bMPS aborts})=1-e^{-\Omega(\sqrt N)}.}
\]
\hfill$\blacksquare$

