\textbf{Claim.} For the square-lattice holographic Clifford circuit on $q=2^m$ dimensional qudits with $m\ge 6$, any classical probabilistic circuit that samples a distribution at constant total-variation distance from the quantum output distribution must have depth $\Omega(\log N)$.

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & \text{If a random circuit ensemble has long-ranged tripartite MIE, then any such classical sampler has depth }\Omega(\log N).\\
(P2) & \text{Long-ranged tripartite MIE means: with constant probability over random }\{h,i,j\},\\
     & \text{the post-measurement one-qubit marginals satisfy }\operatorname{Tr}(\rho_\alpha^2)<c_2<1\text{ for }\alpha\in\{h,i,j\}.\\
(P3) & \text{With constant probability, random qubits }h,i,j\text{ lie in distinct well-separated sites }H,I,J.\\
(P4) & \text{For fixed sites }H,I,J\text{, if }S(\rho_X)>0\text{ for each }X\in\{H,I,J\},\\
     & \text{then a further constant-probability local Clifford projection gives the property in (P2).}\\
(P5) & \text{For stabilizer states, }S(\rho_X)=0\text{ iff }\rho_X\text{ is pure, and otherwise }S(\rho_X)\ge \log 2.\\
(P6) & \Pr\left(\bigcup_{X\in\{H,I,J\}}\{\rho_X\text{ is pure}\}\right)\le \sum_{X\in\{H,I,J\}}\Pr(\rho_X\text{ is pure}).\\
(P7) & \Pr(\rho_X\text{ is pure})\le \mathbb E[\epsilon_X].\\
(P8) & \mathbb E[\epsilon_X]\le \sqrt2\,Z_{\mathrm{loop}}f(Z_{\mathrm{loop}}),\quad f(z):=(e^z-1)/z.\\
(P9) & \nu:=e^{\log\mu-\beta},\quad \beta:=\frac12m\log 2,\quad m\ge 6\Longrightarrow \nu\le \frac13.\\
(P10)& \text{The loop partition bound in Appendix F gives }Z_{\mathrm{loop}}\le z_0<1/(3\sqrt2 f(z_0))\text{ whenever }\nu\le 1/3.
\end{array}
\]

\textbf{Derivation.}
For a fixed $X\in\{H,I,J\}$,
\begin{align}
\Pr(\rho_X\text{ is pure})
&\le \mathbb E[\epsilon_X] && \text{by (P7)}\\
&\le \sqrt2\,Z_{\mathrm{loop}}f(Z_{\mathrm{loop}}) && \text{by (P8)}\\
&\le \sqrt2\,z_0f(z_0) && \text{by (P9) and (P10)}\\
&<\frac13. && \text{by (P10)}
\end{align}
Choose $c_3$ such that
\begin{align}
\sqrt2\,z_0f(z_0)&\le c_3<\frac13. && \text{possible by the strict inequality above}
\end{align}
Then the probability that at least one site marginal is pure is bounded by
\begin{align}
\Pr\left(\bigcup_{X\in\{H,I,J\}}\{\rho_X\text{ is pure}\}\right)
&\le \sum_{X\in\{H,I,J\}}\Pr(\rho_X\text{ is pure}) && \text{by (P6)}\\
&\le 3c_3 && \text{by the fixed-}X\text{ bound}\\
&<1. && \text{since }c_3<1/3
\end{align}
Therefore, with probability at least $1-3c_3>0$,
\begin{align}
S(\rho_X)>0\quad\text{for all }X\in\{H,I,J\}. && \text{by (P5)}
\end{align}
Combining this constant-probability event with the constant-probability geometric event and the constant-probability local Clifford projection gives
\begin{align}
\Pr(\text{long-ranged tripartite MIE})&\ge c_1>0 && \text{by (P2)--(P4)}.
\end{align}
Thus the ensemble satisfies the hypothesis of the classical-depth lower-bound theorem, and so
\begin{align}
\operatorname{depth}(\text{classical sampler})&=\Omega(\log N). && \text{by (P1)}
\end{align}

\textbf{Final Result.}
\[
\boxed{m\ge 6\quad\Longrightarrow\quad \operatorname{depth}(\text{any constant-error classical sampler})=\Omega(\log N).}
\]
\hfill$\blacksquare$
